  const routes = [];
  const extent = CITY.bounds + 30;
  for (const x of ROAD) {
    routes.push({ axis: 'z', lanes: LANES.slice(), x, from: -extent, to: extent });
    routes.push({ axis: 'z', lanes: LANES.slice(), x, from: extent, to: -extent });
