  for (const z of ROAD) {
    routes.push({ axis: 'x', lanes: LANES.slice(), z, from: -extent, to: extent });
    routes.push({ axis: 'x', lanes: LANES.slice(), z, from: extent, to: -extent });
  }
  return routes;
